INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('inari-kon-1mid','Inari Kon Kon','いなり、こんこん、恋いろは。',2014,7.1,'Winter 2014','TV','Finished','https://media.kitsu.app/anime/poster_images/7988/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/20488.jpg','#ff9420','Clumsy, below average intellect, and shy – these are some of the traits that Inari Fushimi possesses. Despite her shortcomings, she is very considerate of others. She can’t ignore anyone''s plea for help! She also has a long time crush on Kouji Tanbabashi, who she admires for being cheerful and always hardworking. The problem is, Inari’s incurable shyness makes it difficult to express her feelings for Kouji.Inari, Konkon, Koi Iroha starts with Inari taking a shortcut to her school. She happens to see a fox pup that’s about to fall to the river. Although she’s running late, she just can’t ignore the pup. Uka-no-Mitama-no-Kami, the god of the Inari Shrine, is thankful for Inari’s kindness towards the young fox, who turns out to be a familiar named Kon. To show her gratitude to Inari, she fulfills one of Inari’s wishes. But the fulfillment of the wish only invites trouble. To compensate, Uka-no-Mitama-no-Kami bestows Inari a small part of her divine power that gives Inari the ability to transform into anyone at will. Inari now possesses a power of a god, even if it''s just a small portion. Otherworldly beings suddenly take an interest in her, for better or worse. What kind of adventure awaits Inari, and will she be able to tell Kouji everything that she has kept in her heart for so long?',NULL,'["Inari, Konkon, Koi Iroha.: Inari, Konkon, Semishigure. (2014)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":7988,"anilist":20488,"mal":20457}',NULL,NULL,10,datetime('now'),'inari kon kon いなり こんこん 恋いろは tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;

