INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('inari-kon-1mid#1','inari-kon-1mid',1,'Inari, First Love, First Change','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/113307/original.jpg','Klutzy and shy Kyoto middle-schooler Inari Fushimi can''t bring herself to open up to her crush. She stops by the local shrine seeking solace and support, but will what she finds there solve her problems... or just cause new ones?','[]','2014-01-16','113307');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('inari-kon-1mid#2','inari-kon-1mid',2,'Ordeals, Secrets, Amaterasu','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/113308/original.jpg','Inari finds a way to spend quality time with her crush after he stays home from school. Amaterasu Ohmikami summons her and Uka to the Celestial Plains, where Inari is tested--and failure means both of their lives will never be the same.','[]','2014-01-23','113308');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('inari-kon-1mid#3','inari-kon-1mid',3,'Elder Brother, Pesky, Excess Love','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/113309/original.jpg','Inari''s brother Touka has been able to see Uka all along! Why does he insist the two stay apart? Meanwhile, Inari is distracted by a mysterious (and cute) boy at school who seems to know her divine secret. Is he really who he seems to be?','[]','2014-01-30','113309');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('inari-kon-1mid#4','inari-kon-1mid',4,'Scarlet, Festival Eve, Romance','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/113310/original.jpg','Inari and Uka bond over their older brothers, and Inari and her friends have fun at the shrine festival. It''s the perfect opportunity to become even closer to her crush. Can our klutzy heroine pull it off without putting her foot in it?','[]','2014-02-06','113310');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('inari-kon-1mid#5','inari-kon-1mid',5,'Jellyfish, Friends, Summer Storm','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/113311/original.jpg','The four friends have what should be a fun overnight at the beach, but Marutamachi and Sumizome aren''t getting along. Can the trip--and their friendships--be salvaged? Meanwhile, Uka may have given away more of her power than she thought...','[]','2014-02-13','113311');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('inari-kon-1mid#6','inari-kon-1mid',6,'Touka, Mistress Uka, A Woman in Love','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/113312/original.jpg','Inari struggles with her divine gift as she tries to help her newest friend, while Touka and Uka spend some quality time together. Sumizome realizes something about herself that could change her relationships in a major way.','[]','2014-02-20','113312');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('inari-kon-1mid#7','inari-kon-1mid',7,'Maiden, Aflutter, Madder Red','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/113313/original.jpg','Inari gets a juicy part in the class play, but something about it doesn''t sit right with her. Uka is summoned to the Celestial Plains for a round of arranged dates with potential suitors. A confession of love may serve a dual purpose.','[]','2014-02-27','113313');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('inari-kon-1mid#8','inari-kon-1mid',8,'Izumo, Arranged Dates, Kerfuffle','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/113314/original.jpg','An impromptu trip to Izumo gets Inari and her brother more involved in divine matters than they''d bargained for. Uka submits herself to arranged dates, but her perfect mate may not be on the roster. Amaterasu puts her foot down.','[]','2014-03-06','113314');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('inari-kon-1mid#9','inari-kon-1mid',9,'Fox, Twilight, Milky Way','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/113315/original.jpg','Inari realizes she didn''t quite follow through on a favor for a classmate and has to deal with the repercussions, while Uka must cope with the fallout of having such a close mortal friend. Will the two be reunited, and at what cost?','[]','2014-03-13','113315');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('inari-kon-1mid#10','inari-kon-1mid',10,'Inari, Konkon, ABCs of Love','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/113316/original.jpg','Pushing herself to her very limits in her attempts to free Uka from her heavenly prison, Inari struggles to overcome her feelings of betrayal and do the right thing--not necessarily the easiest or the most convenient--for both of them.','[]','2014-03-20','113316');

